    tournMissingPrizes: 'For paid tournaments, all 3 prizes must be entered.',
    tournRulesLabel: 'Tournament Rules',
    tournRules1: '1. Each participant enters individually. Players with similar ELO ratings are matched by the system — each pair meets once before the playoffs.\n\n2. All matches are competitive: wins earn ELO points, losses deduct them.\n\n3. Matched players agree on date, time, and court. New matchups are generated weekly. Each player has 1 Joker right — the postponed match must be played within 2 weeks.\n\n4. Coordinate via the "Comment" section on the match card. Once agreed, enter date, time, and venue on the card. After the match both players confirm the score. If the match was abandoned, tap "Can\'t Enter Score" to enter a new date/time and the partial score.\n\n5. If players are tied on every tiebreak stat (points, averaj, set ratio, game ratio) right at the playoff cutoff, an extra round is added before any lot is drawn — tied players are matched against opponents they haven\'t played yet, closest ELO first. This repeats until the tie breaks; a lot draw is only used as a last resort if no more valid matchups remain.',
    tournRules2: '1. You may join as a pre-formed pair, or apply solo — solo applicants are auto-paired by closest ELO rating once the tournament starts. If one solo applicant is left without a match, the lowest-rated one is excluded.\n\n2. For mixed-gender tournaments, the system never pairs two solo women into the same auto-formed team.\n\n3. Each team has 1 joker right. A match must be played weekly; using the joker grants +7 days. The team must still make every reasonable effort to finish in the extended time — if it still can\'t finish, the team that used the joker forfeits.\n\n4. If the opposing team also requests a joker for the same match, it counts as mutual: the +7 days still apply once, but neither team\'s joker right is spent (for weather, court availability, etc.).\n\n5. Teams are matched by closest average ELO; as many rounds as chosen before the playoffs are generated, each team meeting every other team at most once.\n\n6. If teams are tied on points before the playoffs, game ratio (averaj) is used as the tiebreaker.\n\n7. When a team wins or loses, both players individually gain or lose ELO points — the amount is based on the gap between the two teams\' average ELO, using the same point table as other competitive matches.\n\n8. If teams are tied on every tiebreak stat (points, averaj, set ratio, game ratio) right at the playoff cutoff, an extra round is added before any lot is drawn — tied teams are matched against opponents they haven\'t played yet, closest average ELO first. This repeats until the tie breaks; a lot draw is only used as a last resort if no more valid matchups remain.',
    tournRules3: '1. Players enter individually.\n\n2. Once the draw is made, each round\'s opponents are randomly matched, and who plays whom is fixed and known up until the playoffs.\n\n3. Each player has 1 Joker right. A match is required every week. Using the joker on a match grants +7 extra days; if the match still isn\'t finished when time runs out, the player who used the joker forfeits.\n\n4. If both players use the joker for the same match, or use it mutually, the extension is only +7 days (not +7+7) — since both sides did it mutually, neither player\'s joker right is spent.\n\n5. If players are tied on points when reaching the playoff cutoff, the one with the higher game ratio (games won / total games) is ranked first.\n\n6. If players tied at the playoff cutoff are also fully equal on game ratio, set ratio, and game-count ratio, an extra round is added before any draw is made; the tied players are matched against the closest-rated opponents they haven\'t yet played. This repeats until the tie is broken — a random draw is used only as a last resort when no suitable matchup remains.\n\n7. If both sides have availability, players may contact each other and finish their matches earlier if they wish.',
