    tournFeeShared: 'Oyuncular ortaklaşa öder',
    tournFeeSponsored: 'Sponsorlar karşılar',
    tournPrize1: '🥇 1. Ödül *', tournPrize2: '🥈 2. Ödül *', tournPrize3: '🥉 3. Ödül *',
    tournPrize1Opt: '🥇 1. Ödül', tournPrize2Opt: '🥈 2. Ödül', tournPrize3Opt: '🥉 3. Ödül',
    tournSurpriseGifts: '🎁 Sürpriz Hediyeler',
    tournPrizePh: 'ör. 5000 ₺ nakit veya kupa',
    tournMissingPrizes: 'Ücretli turnuvalarda 3 ödül de girilmesi zorunludur.',
    tournRulesLabel: 'Turnuva Kuralları',
    tournRules1: '1. Her oyuncu bireysel olarak katılır. Elo puanları birbirine yakın oyuncular, play-off\'lara kadar birer kez sisteme tarafından eşleştirilir.\n\n2. Turnuva içindeki tüm maçlar rekabetçidir; galip Elo puanı kazanır, mağlup Elo puanı kaybeder.\n\n3. Eşleşen oyuncular tarih, saat ve kortu karşılıklı anlaşarak belirler. Eşleşmeler haftalık oluşturulur. Her oyuncu 1 joker hakkına sahiptir; bu hak kullanıldığında maç 2. haftanın sonuna kadar yapılmak zorundadır.\n\n4. Anlaşma için eşleşme kartındaki "Yorum Yap" bölümü kullanılır. Anlaşma sonrasında tarih, saat ve yer kartına girilir. Maç bittikten sonra skor karşılıklı onaylanır. Maç yarıda kalırsa "Skor Giremiyoruz" butonu ile yeni tarih/saat ve o anki skor girilebilir.\n\n5. Play-off kontenjanı sınırında puan, averaj, set oranı ve oyun oranının tamamı eşit olan oyuncular varsa, kura çekilmeden önce bir tur daha eklenir; eşitliğe karışan oyuncular henüz oynamadıkları, puanı en yakın rakiplerle eşleştirilir. Eşitlik bozulana kadar bu tekrarlanır; kura yalnızca uygun eşleşme kalmadığında son çare olarak kullanılır.',
    tournRules2: '1. Oyuncular turnuvaya çift olarak (takım halinde) katılabilir ya da bireysel başvurabilir — bireysel başvuranlar turnuva başlarken ELO puanı birbirine en yakın olanlarla eşleştirilerek takım yapılır. Tek kalan en düşük ELO puanlı oyuncu turnuvaya katılım sağlayamaz.\n\n2. Karışık (mix) turnuvalarda bireysel katılımcılardan sistem aynı takımda iki kadın oluşturacak şekilde eşleşme yapmaz.\n\n3. Her takımın 1 kez joker hakkı vardır. Haftada bir maç zorunluluğu olup joker hakkı kullanılırsa takıma +7 gün ek süre tanınır. Joker kullanan takım bu sürede maçı bitirmek için gerekli tavizi vermekle yükümlüdür; bitiremezse joker kullanan takım hükmen yenilir.\n\n4. Jokeri kullanan takımın rakibi de aynı maç için karşılıklı joker yaparsa joker hakkı tükenmez, sadece 7 günlük süre bir kez eklenmiş olur (hava şartları, kort temin edilememesi vb. durumlar için).\n\n5. Takımların ELO puan ortalaması alınır ve playoff\'lara kadar kaç maç seçildiyse, her takım diğer her takımla en fazla bir kez eşleşecek şekilde, ortalama puanı en yakın olandan başlanarak her turda rakip eşleşmesi sağlanır.\n\n6. Playoff öncesi lig tablosunda puanı eşit olan takımlar varsa averaj (oynanan oyun oranı) dikkate alınır.\n\n7. Bir takım kazandığında/kaybettiğinde iki oyuncu da bireysel olarak ELO puanı kazanır/kaybeder — miktar, diğer rekabetçi maçlarla aynı puan tablosu kullanılarak iki takımın ortalama ELO farkına göre belirlenir.\n\n8. Play-off kontenjanı sınırında puan, averaj, set oranı ve oyun oranının tamamı eşit olan takımlar varsa, kura çekilmeden önce bir tur daha eklenir; eşitliğe karışan takımlar henüz oynamadıkları, ortalama ELO\'su en yakın rakiplerle eşleştirilir. Eşitlik bozulana kadar bu tekrarlanır; kura yalnızca uygun eşleşme kalmadığında son çare olarak kullanılır.',
    tournRules3: '1. Oyuncular bireysel katılır.\n\n2. Kura çekildiğinde her tur rastgele oyuncular eşleşilir ve play-off\'lara kadar kimin kiminle maç yapacağı bellidir.\n\n3. Her oyuncunun 1 joker hakkı vardır. Haftada 1 maç zorunludur. Joker kullanılan maça +7 gün ek süre tanınır; süre dolmasına rağmen maç bitmezse joker kullanan oyuncu hükmen yenilir.\n\n4. İki oyuncu da aynı maç için joker kullanır ya da karşılıklı joker yaparsa +7 +7 değil sadece +7 olarak uzar; sadece iki taraf da karşılıklı yaptığı için joker hakları tükenmez.\n\n5. Aynı puanlı oyuncular play-off\'a geldiğinde averajı (galibiyet oyunu / toplam oyun) yüksek olan önce alınır.\n\n6. Play-off kontenjanı sınırında puan, averaj, set oranı ve oyun oranının tamamı eşit olan oyuncular varsa, kura çekilmeden önce bir tur daha eklenir; eşitliğe karışan oyuncular henüz oynamadıkları, puanı en yakın rakiplerle eşleştirilir. Eşitlik bozulana kadar bu tekrarlanır; kura yalnızca uygun eşleşme kalmadığında son çare olarak kullanılır.\n\n7. Oyuncular isterlerse iki taraf içinde müsaitlik durumu söz konusu ise yapacakları maçlar için iletişime geçerek daha erken maçlarını tamamlamak isterlerse tamamlayabilirler.',
    tournPartnerTitle: 'Çiftler Rekabetçi',
