    tournFreeNote: 'ℹ️ Бесплатный турнир — организация и управление полностью на вашей ответственности.',
    tournPaidNote: '⚠️ Если вы собираете вступительный взнос, 10% от общей собранной суммы удерживается как доля платформы.',
    tournCourtFeeWho: 'Кто оплачивает аренду корта?',
    tournFeeIncluded: 'Включено во вступительный взнос',
    tournFeeShared: 'Игроки делят между собой',
