    ratingChangeInfoBody: 'Рейтинг — это не простое деление на победу/поражение, а расчёт "каким должен быть ваш рейтинг против этого соперника, чтобы получить такой результат".\n\n• Если у вас уже высокий рейтинг и вы обыгрываете гораздо более слабого соперника — это "ожидаемый" результат, ваш рейтинг почти не меняется.\n• Если у вас низкий рейтинг и вы обыгрываете гораздо более сильного соперника — это большой сюрприз, ваш рейтинг заметно вырастет.\n• Та же логика применяется в обратную сторону при поражениях.\n\nПоэтому в парной игре, даже когда ваша команда побеждает, вы и ваш партнёр можете получить разное количество очков — победа над слабым соперником мало что доказывает, если вы уже были сильны.\n\nКроме того, если у вашего соперника пока мало истории матчей в этой системе, этот матч учитывается в вашем рейтинге с меньшим весом.',
