    tournPrize1: '🥇 Preis für 1. Platz *', tournPrize2: '🥈 Preis für 2. Platz *', tournPrize3: '🥉 Preis für 3. Platz *',
    tournPrize1Opt: '🥇 Preis für 1. Platz', tournPrize2Opt: '🥈 Preis für 2. Platz', tournPrize3Opt: '🥉 Preis für 3. Platz',
    tournSurpriseGifts: '🎁 Überraschungsgeschenke',
    tournPrizePh: 'z.B. 5000 ₺ Bargeld oder Pokal',
    tournMissingPrizes: 'Bei kostenpflichtigen Turnieren müssen alle 3 Preise eingegeben werden.',
    tournRulesLabel: 'Turnierregeln',
    tournRules1: '1. Jeder Teilnehmer tritt einzeln an. Spieler mit ähnlichem ELO-Rang werden vom System zusammengeführt — jedes Paar trifft sich einmal vor den Playoffs.\n\n2. Alle Matches sind Wettkampf: Siege bringen ELO-Punkte, Niederlagen ziehen sie ab.\n\n3. Vermittelte Spieler vereinbaren Datum, Uhrzeit und Platz. Neue Paarungen werden wöchentlich erstellt. Jeder Spieler hat 1 Joker-Recht — das verschobene Match muss innerhalb von 2 Wochen gespielt werden.\n\n4. Koordiniert euch über den "Kommentar"-Bereich der Match-Karte. Nach Einigung Datum, Uhrzeit und Ort auf der Karte eintragen. Nach dem Match bestätigen beide Spieler das Ergebnis. Wurde das Match abgebrochen, tippe auf "Ergebnis kann nicht eingegeben werden", um ein neues Datum/Uhrzeit und das Teilergebnis einzugeben.\n\n5. Sind Spieler bei allen Tiebreak-Werten (Punkte, Durchschnitt, Satzverhältnis, Spielverhältnis) genau an der Playoff-Grenze gleich, wird vor jeder Auslosung eine zusätzliche Runde hinzugefügt — gleichstehende Spieler werden gegen Gegner vermittelt, gegen die sie noch nicht gespielt haben, zuerst nach nächstliegendem ELO. Dies wiederholt sich, bis der Gleichstand aufgelöst ist; eine Auslosung wird nur als letztes Mittel verwendet, wenn keine gültigen Paarungen mehr übrig sind.',
    tournRules2: '1. Du kannst als bereits gebildetes Paar beitreten oder dich einzeln bewerben — Einzelbewerber werden nach Turnierstart automatisch nach nächstliegendem ELO-Rang gepaart. Bleibt ein Einzelbewerber ohne Partner, wird der mit dem niedrigeren Rang ausgeschlossen.\n\n2. Bei gemischtgeschlechtlichen Turnieren paart das System niemals zwei einzelne Frauen im selben automatisch gebildeten Team.\n\n3. Jedes Team hat 1 Joker-Recht. Ein Match muss wöchentlich gespielt werden; die Nutzung des Jokers gewährt +7 Tage. Das Team muss trotzdem alle zumutbaren Anstrengungen unternehmen, um in der verlängerten Zeit fertig zu werden — gelingt das trotzdem nicht, verliert das Team, das den Joker genutzt hat.\n\n4. Fragt das gegnerische Team ebenfalls einen Joker für dasselbe Match an, gilt dies als gegenseitig: die +7 Tage gelten trotzdem einmal, aber keinem der Teams wird sein Joker-Recht abgezogen (wegen Wetter, Platzverfügbarkeit usw.).\n\n5. Teams werden nach nächstliegendem Durchschnitts-ELO vermittelt; es werden so viele Runden vor den Playoffs erstellt wie gewählt, wobei jedes Team jedes andere höchstens einmal trifft.\n\n6. Sind Teams vor den Playoffs bei den Punkten gleich, dient das Spielverhältnis (Durchschnitt) als Tiebreaker.\n\n7. Gewinnt oder verliert ein Team, erhalten oder verlieren beide Spieler einzeln ELO-Punkte — der Betrag basiert auf der Differenz des Durchschnitts-ELO der beiden Teams, nach derselben Punktetabelle wie andere Wettkampfmatches.\n\n8. Sind Teams bei allen Tiebreak-Werten (Punkte, Durchschnitt, Satzverhältnis, Spielverhältnis) genau an der Playoff-Grenze gleich, wird vor jeder Auslosung eine zusätzliche Runde hinzugefügt — gleichstehende Teams werden gegen Gegner vermittelt, gegen die sie noch nicht gespielt haben, zuerst nach nächstliegendem Durchschnitts-ELO. Dies wiederholt sich, bis der Gleichstand aufgelöst ist; eine Auslosung wird nur als letztes Mittel verwendet, wenn keine gültigen Paarungen mehr übrig sind.',
    tournRules3: '1. Spieler treten einzeln an.\n\n2. Nach der Auslosung werden die Gegner jeder Runde zufällig zugeordnet, und wer gegen wen spielt, steht bis zu den Playoffs fest und ist bekannt.\n\n3. Jeder Spieler hat 1 Joker-Recht. Ein Match ist wöchentlich erforderlich. Die Nutzung des Jokers für ein Match gewährt +7 zusätzliche Tage; ist das Match nach Ablauf der Zeit immer noch nicht beendet, verliert der Spieler, der den Joker genutzt hat.\n\n4. Nutzen beide Spieler den Joker für dasselbe Match, oder nutzen sie ihn gegenseitig, beträgt die Verlängerung nur +7 Tage (nicht +7+7) — da beide Seiten dies gegenseitig taten, wird keinem Spieler sein Joker-Recht abgezogen.\n\n5. Sind Spieler bei Erreichen der Playoff-Grenze bei den Punkten gleich, wird derjenige mit dem höheren Spielverhältnis (gewonnene Spiele / Spiele gesamt) höher eingestuft.\n\n6. Sind an der Playoff-Grenze gleichstehende Spieler auch bei Spielverhältnis, Satzverhältnis und Spielanzahlverhältnis völlig gleich, wird vor jeder Auslosung eine zusätzliche Runde hinzugefügt; die gleichstehenden Spieler werden gegen die nächstplatzierten Gegner vermittelt, gegen die sie noch nicht gespielt haben. Dies wiederholt sich, bis der Gleichstand aufgelöst ist — eine Zufallsauslosung wird nur als letztes Mittel verwendet, wenn keine passende Paarung mehr übrig bleibt.\n\n7. Haben beide Seiten Zeit, können Spieler sich untereinander absprechen und ihre Matches auf Wunsch früher beenden.',
