    ratingChangeInfoBody: 'Der Rang ist keine einfache Sieg-/Niederlage-Aufteilung — er basiert darauf, "wie hoch dein Rang gegen diesen Gegner sein müsste, um dieses Ergebnis zu erzielen".\n\n• Bist du bereits hoch eingestuft und besiegst einen deutlich schwächeren Gegner, ist das das "erwartete" Ergebnis — dein Rang ändert sich kaum.\n• Bist du niedrig eingestuft und besiegst einen deutlich stärkeren Gegner, ist das eine große Überraschung — dein Rang steigt deutlich.\n• Die gleiche Logik gilt umgekehrt bei Niederlagen.\n\nDeshalb können im Doppel, selbst wenn dein Team gewinnt, du und dein Partner unterschiedlich viele Punkte erhalten — ein schwacher Gegner zu besiegen beweist wenig, wenn du bereits stark warst.\n\nHat dein Gegner außerdem noch wenig Match-Historie in diesem System, zählt dieses Match weniger für deinen Rang.',
